		list.add(new AddressColumnConstraint(new(UnsignedLongConstraintEditor.MAX_VALUE, new UnsignedLongConstraintEditorProvider())));
		list.add(new AddressColumnConstraint(new(BigInteger.ZERO, new UnsignedLongConstraintEditorProvider())));
		list.add(new AddressColumnConstraint(new(BigInteger.ZERO, UnsignedLongConstraintEditor.MAX_VALUE, new UnsignedLongRangeEditorProvider())));
		list.add(new AddressColumnConstraint(new(BigInteger.ZERO, UnsignedLongConstraintEditor.MAX_VALUE, new UnsignedLongRangeEditorProvider())));

		// @formatter:on

		return list;

	}

	/**
	 * This is a special non-discoverable mapper to be used by the special AddressColumnConstraint
	 * class below.  This is special because we don't want to use any old BigInteger editor, but
	 * rather an unsigned editor that makes more sense for addresses.
	 */
	private static class AddressToBigIntegerMapper : ColumnTypeMapper<Address, BigInteger> {

		/* @Override */
